// ===============================
// Mini Tower Defense (15x10, BFS) - Full JS
// - Enemies rendered as Aliens on Canvas (drawAlien style)
// - Better-looking towers (DOM markup + injected CSS)
// - In-game How-To-Play modal (generated by JS)
// ===============================

// ---------- 0) Config ----------
const COLS = 15;
const ROWS = 10;

const START = { x: 0, y: Math.floor(ROWS / 2) };
const END = { x: COLS - 1, y: Math.floor(ROWS / 2) };

const TOWER_COST = 25;
const TOWER_RANGE_CELLS = 3;
const TOWER_COOLDOWN = 0.55; // sec
const TOWER_DAMAGE = 18;

const ENEMY_BASE_HP = 80;
const ENEMY_SPEED = 2.6; // cells/sec
const SPAWN_INTERVAL = 1.15; // sec
const GOLD_PER_KILL = 8;
const LIFE_LOSS_ON_LEAK = 1;

const SHOW_PATH_HINT = true; // 想關掉 BFS 路徑提示就改 false

// ---------- 1) State ----------
let running = false;
let paused = false;

let gold = 120;
let life = 20;
let wave = 1;

let towers = [];   // {x,y, range2, cooldown, lastShot, damage}
let enemies = [];  // {id,x,y,hp,maxHp,path,pathIdx,progress,alive,color}
let nextEnemyId = 1;

let gridBlocked = [];   // [ROWS][COLS] boolean
let currentPath = null; // [{x,y},...]

let lastTime = 0;
let spawnAcc = 0;

let cellEls = []; // 1D cells

// ---------- 2) DOM ----------
const gridEl = document.getElementById("grid");
const unitsEl = document.getElementById("units");

const goldEl = document.getElementById("gold");
const lifeEl = document.getElementById("life");
const waveEl = document.getElementById("wave");
const aliveEl = document.getElementById("alive");
const msgEl = document.getElementById("msg");

const startBtn = document.getElementById("startBtn");
const pauseBtn = document.getElementById("pauseBtn");
const resetBtn = document.getElementById("resetBtn");

// ---------- 3) Inject UI (canvas + modal + nicer tower css) ----------
