document.body.appendChild(overlay);

function openHowTo() { overlay.style.display = "flex"; }
function closeHowTo() { overlay.style.display = "none"; }

// Add a "How to Play" button into HUD (no HTML edit needed)
(function addHowToBtn() {
  const btn = document.createElement("button");
  btn.className = "btn";
  btn.textContent = "遊戲說明";
  btn.addEventListener("click", openHowTo);
  // 插在 startBtn 前面，介面自然
  startBtn.parentNode.insertBefore(btn, startBtn);
})();

document.getElementById("howClose").addEventListener("click", closeHowTo);
document.getElementById("howStart").addEventListener("click", () => {
  closeHowTo();
  if (!running) startGame();
});

// ---------- 4) Canvas setup ----------
let uCanvas = document.getElementById("uCanvas");
if (!uCanvas) {
  // 如果你的 HTML 沒放 canvas，我這裡自動塞進 units
  uCanvas = document.createElement("canvas");
  uCanvas.id = "uCanvas";
  unitsEl.appendChild(uCanvas);
}
const ctx = uCanvas.getContext("2d");

function resizeCanvasToUnits() {
  const rect = unitsEl.getBoundingClientRect();
  const dpr = window.devicePixelRatio || 1;
  uCanvas.width = Math.round(rect.width * dpr);
  uCanvas.height = Math.round(rect.height * dpr);
  uCanvas.style.width = rect.width + "px";
  uCanvas.style.height = rect.height + "px";
  // 後面使用 CSS 像素座標繪圖
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
}
window.addEventListener("resize", resizeCanvasToUnits);

// ---------- 5) Helpers ----------
function idx(x, y) { return y * COLS + x; }
function inBounds(x, y) { return x >= 0 && x < COLS && y >= 0 && y < ROWS; }

function getCellMetrics() {
  const styles = getComputedStyle(document.documentElement);
  const cell = parseFloat(styles.getPropertyValue("--cell")) || 46;
  const gap = parseFloat(styles.getPropertyValue("--gap")) || 6;
  return { cell, gap };
}

function gridToPixelCenter(x, y) {
  const { cell, gap } = getCellMetrics();
  return {
    x: x * (cell + gap) + cell / 2,
    y: y * (cell + gap) + cell / 2
  };
}

let msgTimer = null;
function flashMsg(text) {
  msgEl.textContent = text;
  clearTimeout(msgTimer);
  msgTimer = setTimeout(() => {
    msgEl.textContent = "提示：點格子放塔；堵死路徑會被拒絕。點「遊戲說明」可再查看玩法。";
  }, 1800);
}

// ---------- 6) BFS Pathfinding ----------
function bfsPath(start, goal) {
  const q = [];
  const prev = Array.from({ length: ROWS }, () => Array(COLS).fill(null));
  const visited = Array.from({ length: ROWS }, () => Array(COLS).fill(false));

  q.push(start);
  visited[start.y][start.x] = true;

  const dirs = [
    { dx: 1, dy: 0 }, { dx: -1, dy: 0 },
    { dx: 0, dy: 1 }, { dx: 0, dy: -1 }
  ];

  while (q.length) {
    const cur = q.shift();
    if (cur.x === goal.x && cur.y === goal.y) break;

    for (const d of dirs) {
      const nx = cur.x + d.dx;
      const ny = cur.y + d.dy;
      if (!inBounds(nx, ny)) continue;
      if (visited[ny][nx]) continue;

      // blocked cells not walkable (except start/end)
      if (!(nx === goal.x && ny === goal.y) && !(nx === start.x && ny === start.y)) {
        if (gridBlocked[ny][nx]) continue;
      }

      visited[ny][nx] = true;
      prev[ny][nx] = cur;
      q.push({ x: nx, y: ny });
    }
  }

  if (!visited[goal.y][goal.x]) return null;

  const path = [];
  let cur = goal;
  while (cur) {
    path.push(cur);
    cur = prev[cur.y][cur.x];
  }
  path.reverse();
  return path;
}

function renderPath(path) {
  // 清 path 標記
  for (const cell of cellEls) cell.classList.remove("path");
  if (!SHOW_PATH_HINT) return;
  if (!path) return;
  for (const p of path) {
    if ((p.x === START.x && p.y === START.y) || (p.x === END.x && p.y === END.y)) continue;
    cellEls[idx(p.x, p.y)].classList.add("path");
  }
}

// ---------- 7) Drawing: Aliens + HP + Beams ----------
function drawAlien(x, y, r, color = "#9369ffff") {
  // 圓臉
  ctx.beginPath();
  ctx.fillStyle = color;
  ctx.arc(x, y, r, 0, Math.PI * 2);
  ctx.fill();

  ctx.strokeStyle = "#000e44ff";
  ctx.lineWidth = 0;
  ctx.stroke();

  // 眼睛
  const eyeOffset = r * 0.45;
  const eyeR = r * 0.25;

  function drawEye(cx, cy) {
    ctx.beginPath();
    ctx.fillStyle = "#ffffff";
    ctx.arc(cx, cy, eyeR, 0, Math.PI * 2);
    ctx.fill();

    ctx.beginPath();
    ctx.fillStyle = "#000000";
    ctx.arc(cx, cy, eyeR * 0.5, 0, Math.PI * 2);
    ctx.fill();
  }

  drawEye(x - eyeOffset, y - r * 0.1);
  drawEye(x + eyeOffset, y - r * 0.1);

  // 觸角
  const antennaY = y - r * 1.1;
  const ballR = r * 0.18;

  ctx.strokeStyle = color;
  ctx.lineWidth = 4;

  ctx.beginPath();
  ctx.moveTo(x - r * 0.35, y - r * 0.4);
  ctx.lineTo(x - r * 0.55, antennaY);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(x + r * 0.35, y - r * 0.4);
  ctx.lineTo(x + r * 0.55, antennaY);
  ctx.stroke();

  ctx.beginPath();
  ctx.fillStyle = color;
  ctx.arc(x - r * 0.55, antennaY, ballR, 0, Math.PI * 2);
  ctx.fill();

  ctx.beginPath();
  ctx.fillStyle = color;
  ctx.arc(x + r * 0.55, antennaY, ballR, 0, Math.PI * 2);
  ctx.fill();
}

function drawHPBar(px, py, r, hp, maxHp) {
  const { cell } = getCellMetrics();
  const w = cell * 0.72;
  const h = 6;
  const ratio = Math.max(0, Math.min(1, hp / maxHp));

  ctx.globalAlpha = 0.9;
  ctx.fillStyle = "rgba(255,255,255,0.18)";
  ctx.fillRect(px - w / 2, py - r - 14, w, h);

  ctx.fillStyle = "rgba(120,255,160,0.65)";
  ctx.fillRect(px - w / 2, py - r - 14, w * ratio, h);
  ctx.globalAlpha = 1.0;
}

// 短暫光束（存到 queue，渲染時淡出）
const beams = []; // {x1,y1,x2,y2,t0}
function addBeam(x1, y1, x2, y2) {
  beams.push({ x1, y1, x2, y2, t0: performance.now() });
}
function renderBeams() {
  const now = performance.now();
  for (let i = beams.length - 1; i >= 0; i--) {
    const b = beams[i];
    const age = (now - b.t0) / 1000;
    if (age > 0.12) { beams.splice(i, 1); continue; }
    const alpha = 1 - age / 0.12;

    ctx.globalAlpha = alpha;
    ctx.lineWidth = 3;
    ctx.strokeStyle = "rgba(255,230,120,0.85)";
    ctx.beginPath();
    ctx.moveTo(b.x1, b.y1);
    ctx.lineTo(b.x2, b.y2);
    ctx.stroke();
    ctx.globalAlpha = 1;
  }
}

function renderAllCanvas() {
  // clear canvas
  const rect = unitsEl.getBoundingClientRect();
  ctx.clearRect(0, 0, rect.width, rect.height);

  // beams first (behind aliens) or after (front) - choose after for clarity
  // draw aliens
  const { cell } = getCellMetrics();
  const r = cell * 0.31;

  for (const e of enemies) {
    if (!e.alive) continue;
    const p = gridToPixelCenter(e.x, e.y);
    drawAlien(p.x, p.y, r, e.color || "#9369ffff");
    drawHPBar(p.x, p.y, r, e.hp, e.maxHp);
  }

  renderBeams();
}

// ---------- 8) Grid / towers ----------
function initGrid() {
  gridEl.innerHTML = "";
  cellEls = [];
  gridBlocked = Array.from({ length: ROWS }, () => Array(COLS).fill(false));

  for (let y = 0; y < ROWS; y++) {
    for (let x = 0; x < COLS; x++) {
      const cell = document.createElement("div");
      cell.className = "cell";
      cell.dataset.x = String(x);
      cell.dataset.y = String(y);

      if (x === START.x && y === START.y) cell.classList.add("start");
      if (x === END.x && y === END.y) cell.classList.add("end");

      cell.addEventListener("click", onCellClick);
      gridEl.appendChild(cell);
      cellEls.push(cell);
    }
  }
}

function paintTowerCell(x, y) {
  const cell = cellEls[idx(x, y)];
  cell.classList.add("tower");

  // clear existing art (safe)
  cell.querySelectorAll(".towerArt").forEach(n => n.remove());

  // tower markup
  const art = document.createElement("div");
  art.className = "towerArt";
  art.innerHTML = `
    <div class="towerGlow"></div>
    <div class="towerBase"></div>
    <div class="towerCore"></div>
    <div class="towerBarrel"></div>
  `;
  cell.appendChild(art);
}

function makeTower(x, y) {
  return {
    x, y,
    range2: TOWER_RANGE_CELLS * TOWER_RANGE_CELLS,
    cooldown: TOWER_COOLDOWN,
    lastShot: -Infinity,
    damage: TOWER_DAMAGE
  };
}

// ---------- 9) Range + target selection + cooldown ----------
function inRangeSquared(tower, enemy) {
  const dx = tower.x - enemy.x;
  const dy = tower.y - enemy.y;
  return (dx * dx + dy * dy) <= tower.range2;
}

// 目標策略：最前（progress 最大）
// （這等價於 priority = -progress 的優先隊列取最小；小遊戲用線掃更簡單）
function pickTargetLeading(tower) {
  let best = null;
  let bestProg = -Infinity;
  for (const e of enemies) {
    if (!e.alive) continue;
    if (!inRangeSquared(tower, e)) continue;
    if (e.progress > bestProg) {
      bestProg = e.progress;
      best = e;
    }
  }
  return best;
}

function towerTryShoot(tower, nowSec) {
  if (nowSec - tower.lastShot < tower.cooldown) return;

  const target = pickTargetLeading(tower);
  if (!target) return;

  tower.lastShot = nowSec;

  // damage
  target.hp -= tower.damage;
  if (target.hp <= 0) {
    target.hp = 0;
    killEnemy(target);
  }

  // beam effect
  const a = gridToPixelCenter(tower.x, tower.y);
  const b = gridToPixelCenter(target.x, target.y);
  addBeam(a.x, a.y, b.x, b.y);
}

// ---------- 10) Enemies ----------
function spawnEnemy() {
  if (!currentPath) return;
  const hp = ENEMY_BASE_HP + (wave - 1) * 14;

  const palette = ["#9369ffff", "#6fe7ffff", "#7bffb7ff", "#ffcf6fff"];
  const color = palette[Math.floor(Math.random() * palette.length)];

  enemies.push({
    id: nextEnemyId++,
    x: START.x,
    y: START.y,
    hp,
    maxHp: hp,
    path: currentPath,
    pathIdx: 0,
    progress: 0,
    alive: true,
    color
  });
}

function killEnemy(enemy) {
  enemy.alive = false;
  gold += GOLD_PER_KILL;
  updateHUD();
}

function leakEnemy(enemy) {
  enemy.alive = false;
  life -= LIFE_LOSS_ON_LEAK;
  if (life < 0) life = 0;
  updateHUD();
  if (life <= 0) gameOver();
}

function updateEnemy(enemy, dt) {
  if (!enemy.alive) return;
  const path = enemy.path;
  if (!path || path.length < 2) return;

  const nextIdx = Math.min(enemy.pathIdx + 1, path.length - 1);
  const nextNode = path[nextIdx];

  const vx = nextNode.x - enemy.x;
  const vy = nextNode.y - enemy.y;
  const dist = Math.hypot(vx, vy);

  const step = ENEMY_SPEED * dt;

  if (dist <= step) {
    enemy.x = nextNode.x;
    enemy.y = nextNode.y;
    enemy.pathIdx = nextIdx;
    enemy.progress = enemy.pathIdx;

    // reached end
    if (enemy.x === END.x && enemy.y === END.y) {
      leakEnemy(enemy);
      return;
    }
  } else {
    enemy.x += (vx / dist) * step;
    enemy.y += (vy / dist) * step;

    // smooth progress
    enemy.progress = enemy.pathIdx + (step / dist);
  }
}

// ---------- 11) Placing towers (with BFS validation) ----------
function onCellClick(e) {
  if (!running || paused) return;

  const x = Number(e.currentTarget.dataset.x);
  const y = Number(e.currentTarget.dataset.y);

  if ((x === START.x && y === START.y) || (x === END.x && y === END.y)) {
    flashMsg("起點/終點不能放塔。");
    return;
  }

  if (gridBlocked[y][x]) {
    flashMsg("這格已經有塔了。");
    return;
  }

  if (gold < TOWER_COST) {
    flashMsg("金幣不足。");
    return;
  }

  // try place -> bfs
  gridBlocked[y][x] = true;
  const newPath = bfsPath(START, END);

  if (!newPath) {
    gridBlocked[y][x] = false;
    flashMsg("❌ 這樣會堵死路徑，放塔被拒絕。");
    return;
  }

  // place success
  gold -= TOWER_COST;
  towers.push(makeTower(x, y));
  paintTowerCell(x, y);

  currentPath = newPath;
  renderPath(currentPath);

  // re-path all alive enemies from their rounded cell to END
  for (const en of enemies) {
    if (!en.alive) continue;
    const cell = { x: Math.round(en.x), y: Math.round(en.y) };
    const p = bfsPath(cell, END);
    if (p) {
      en.path = p;
      en.pathIdx = 0;
      en.progress = 0;
    }
  }

  updateHUD();
}

// ---------- 12) HUD ----------
function updateHUD() {
  goldEl.textContent = String(gold);
  lifeEl.textContent = String(life);
  waveEl.textContent = String(wave);
  aliveEl.textContent = String(enemies.filter(e => e.alive).length);
}

// ---------- 13) Game flow ----------
function setupGame() {
  towers = [];
  enemies = [];
  nextEnemyId = 1;

  gold = 120;
  life = 20;
  wave = 1;

  initGrid();
  currentPath = bfsPath(START, END);
  renderPath(currentPath);

  running = false;
  paused = false;
  spawnAcc = 0;

  updateHUD();
  resizeCanvasToUnits();
  renderAllCanvas();

  flashMsg("提示：點格子放塔；堵死路徑會被拒絕。點「遊戲說明」可看玩法。");
}

function startGame() {
  if (running) return;
  if (!currentPath) {
    flashMsg("地圖目前沒有可行路徑（理論上不該發生）。");
    return;
  }
  running = true;
  paused = false;

  startBtn.disabled = true;
  pauseBtn.textContent = "暫停";

  lastTime = performance.now() / 1000;
  spawnAcc = 0;

  flashMsg("✅ 遊戲開始！快放塔擋外星人～");
  requestAnimationFrame(loop);
}

function togglePause() {
  if (!running) return;
  paused = !paused;
  pauseBtn.textContent = paused ? "繼續" : "暫停";
  if (!paused) {
    lastTime = performance.now() / 1000;
    requestAnimationFrame(loop);
  }
}

function restart() {
  startBtn.disabled = false;
  setupGame();
  flashMsg("已重開。按「開始」或打開「遊戲說明」開始玩。");
}

function gameOver() {
  running = false;
  paused = false;
  startBtn.disabled = false;
  pauseBtn.textContent = "暫停";
  flashMsg("💀 Game Over！按「重開」再試一次。");
}

// ---------- 14) Main loop ----------
function loop() {
  if (!running || paused) return;

  const nowSec = performance.now() / 1000;
  const dt = Math.min(0.05, nowSec - lastTime);
  lastTime = nowSec;

  // wave progression: every 18 seconds (simple demo)
  const targetWave = 1 + Math.floor(nowSec / 18);
  if (targetWave > wave) {
    wave = targetWave;
    updateHUD();
    flashMsg(`🌊 進入第 ${wave} 波！敵人更硬、生成更快`);
  }

  // spawn
  spawnAcc += dt;
  const interval = Math.max(0.55, SPAWN_INTERVAL - (wave - 1) * 0.06);
  while (spawnAcc >= interval) {
    spawnAcc -= interval;
    spawnEnemy();
  }

  // move enemies
  for (const e of enemies) updateEnemy(e, dt);

  // towers shoot (cooldown scheduling)
  for (const t of towers) towerTryShoot(t, nowSec);

  updateHUD();
  renderAllCanvas();

  requestAnimationFrame(loop);
}

// ---------- 15) Wire buttons ----------
startBtn.addEventListener("click", () => {
  // 第一次點開始時，先跳出教學更友善
  if (!running) openHowTo();
  else startGame();
});
pauseBtn.addEventListener("click", togglePause);
resetBtn.addEventListener("click", restart);

// ---------- 16) Boot ----------
setupGame();